from taf.gnb.oam.coam.admin.schemas.procedure.ccm_uplink_admin21b import CCMUplink


class CCMUplinkPucch(CCMUplink):
    def __init__(self, nrcell_rdn, nrarfcn_ul, nrarfcn_dl, reporting_time_interval, beam_pattern_id, ru_mode, phys_cell_id,
                 performance_test_type, receiving_slot, expectation_slot, pucch_format, format3_additional_dmrs,
                 prb_offset, largest_prb_index, num_pucch_symbol, num_payload_bit, pucch_payload_content):

        super(CCMUplinkPucch, self).__init__(nrcell_rdn=nrcell_rdn,
                                             nrarfcn_ul=nrarfcn_ul,
                                             nrarfcn_dl=nrarfcn_dl,
                                             reporting_time_interval=reporting_time_interval,
                                             beam_pattern_id=beam_pattern_id,
                                             performance_test_type=performance_test_type,
                                             ru_mode=ru_mode,
                                             phys_cell_id=phys_cell_id)
        self.pucch_params = {"receivingSlot": self.validate_param('receivingSlot',
                                                                  receiving_slot,
                                                                  (0 <= receiving_slot <= 1023)),
                             "expectationSlot": self.validate_param('expectationSlot',
                                                                    expectation_slot,
                                                                    (0 <= expectation_slot <= 1023)),
                             "pucchFormat": self.validate_param('pucchFormat',
                                                                pucch_format,
                                                                (pucch_format in ("F0", "F1", "F2", "F3"))),
                             "format3AdditionalDmrs": self.validate_param('format3AdditionalDmrs',
                                                                          format3_additional_dmrs,
                                                                          (format3_additional_dmrs in ("Disabled", ))),
                             "prbOffset": self.validate_param('prbOffset',
                                                              prb_offset,
                                                              (0 <= prb_offset <= 272)),
                             "largestPrbIndex": self.validate_param('largestPrbIndex',
                                                                    largest_prb_index,
                                                                    (0 <= largest_prb_index <= 272)),
                             "numPucchSymbol": self.validate_param('numPucchSymbol',
                                                                   num_pucch_symbol,
                                                                   (0 <= num_pucch_symbol <= 255)),
                             "numPayloadBit": self.validate_param('numPayloadBit',
                                                                  num_payload_bit,
                                                                  (0 <= num_payload_bit <= 255)),
                             "pucchPayloadContent": self.validate_param('pucchPayloadContent',
                                                                        pucch_payload_content,
                                                                        (0 <= pucch_payload_content <= 4294967295))
                             }

    @classmethod
    def from_response_dict(cls, response_dict):
        def _get_pucch_param(parameter):
            return response_dict['params']['pucchParams'][parameter]

        def _get_optional_param(test_type, parameter):
            test_type_dict = response_dict['params'][test_type]
            return test_type_dict.get(parameter)

        nrcell_rdn = response_dict['nrcell_rDN']
        params = response_dict['params']
        nrarfcn_ul = params['nrarfcnUl'] if 'nrarfcnUl' in params else None
        nrarfcn_dl = params['nrarfcnDl'] if 'nrarfcnDl' in params else None
        reporting_time_interval = params['reportingTimeInterval']
        beam_pattern_id = params['beamPatternId']
        ru_mode = params['ruMode']
        phys_cell_id = params['physCellId']
        performance_test_type = params['performanceTestType']
        pucch_params = {"receivingSlot": _get_pucch_param('receivingSlot'),
                        "expectationSlot": _get_pucch_param('expectationSlot'),
                        "pucchFormat": _get_pucch_param('pucchFormat'),
                        "format3AdditionalDmrs": _get_pucch_param('format3AdditionalDmrs'),
                        "prbOffset": _get_pucch_param('prbOffset'),
                        "largestPrbIndex": _get_pucch_param('largestPrbIndex'),
                        "numPucchSymbol": _get_pucch_param('numPucchSymbol'),
                        "numPayloadBit": _get_pucch_param('numPayloadBit'),
                        "pucchPayloadContent": _get_pucch_param('pucchPayloadContent')}

        return cls(nrcell_rdn=nrcell_rdn,
                   nrarfcn_ul=nrarfcn_ul,
                   nrarfcn_dl=nrarfcn_dl,
                   reporting_time_interval=reporting_time_interval,
                   beam_pattern_id=beam_pattern_id,
                   ru_mode=ru_mode,
                   phys_cell_id=phys_cell_id,
                   performance_test_type=performance_test_type,
                   receiving_slot=pucch_params['receivingSlot'],
                   expectation_slot=pucch_params['expectationSlot'],
                   pucch_format=pucch_params['pucchFormat'],
                   format3_additional_dmrs=pucch_params['format3AdditionalDmrs'],
                   prb_offset=pucch_params['prbOffset'],
                   largest_prb_index=pucch_params['largestPrbIndex'],
                   num_pucch_symbol=pucch_params['numPucchSymbol'],
                   num_payload_bit=pucch_params['numPayloadBit'],
                   pucch_payload_content=pucch_params['pucchPayloadContent']
                   )

    def as_dict(self):
        attributes = super(CCMUplinkPucch, self).as_dict()

        self.pucch_params = self._remove_empty_params(self.pucch_params)
        attributes['params']['pucchParams'] = self.pucch_params

        return attributes
